import React, { useState, forwardRef } from 'react';
import MDEditor from '@uiw/react-md-editor';
import { useTranslation } from 'react-i18next';
import { editorShortcutListener } from '../utils/editor';

interface EditableNoteProps {
  initialContent: string;
  onSave: (content: string) => void;
  onCancel: () => void;
}

const EditableNote = forwardRef<HTMLDivElement, EditableNoteProps>(
  ({ initialContent, onSave, onCancel }, ref) => {
    const { t } = useTranslation();
    const [localContent, setLocalContent] = useState(initialContent);

    const handleSave = () => {
      onSave(localContent);
    };

    const editNoteHandleKeyDown = editorShortcutListener({ save: handleSave, cancel: onCancel });

    return (
      <div ref={ref}>
        <MDEditor
          value={localContent}
          onChange={(value) => setLocalContent(value || '')}
          preview="edit"
          onKeyDown={editNoteHandleKeyDown}
          height={400}
          className="mb-4"
        />
        <button onClick={handleSave} className="action-primary-button">
          {t('action.save')}
        </button>
        <button onClick={onCancel} className="action-secondary-button ml-2">
          {t('action.cancel')}
        </button>
      </div>
    );
  }
);

export default EditableNote; 