import { openDB, DBSchema, IDBPDatabase } from 'idb';
import { Note, SortOption, Todo, DateRange } from '../types';
import { produce } from 'immer';

interface NoteWithLegacyFields extends Note {
  ctime?: string;  // 旧字段，可选
  mtime?: string;  // 旧字段，可选
}

// ... 在 NotesDB interface 中添加
interface NotesDB extends DBSchema {
  notes: {
    key: string;
    value: NoteWithLegacyFields;  // 使用新的接口类型
    indexes: { 
      'by-updated': string, 
      'by-created': string,
      'by-status': string,
      'by-mtime'?: string,  // 添加旧索引，使用可选属性
      'by-ctime'?: string   // 添加旧索引，使用可选属性
    };
  };
  sync: {
    key: 'lastSync';
    value: {
      timestamp: string;
    };
  };
  todos: {
    key: string;
    value: Todo;
    indexes: {
      'by-parent': string;
      'by-updated': string;
    };
  };
}

export class DatabaseService {
  private static dbName = 'notes-db';
  private static db: IDBPDatabase<NotesDB> | undefined;

  static async init() {
    if (DatabaseService.db != undefined) return;

    const latestVersion = 4;
    DatabaseService.db = await openDB<NotesDB>(DatabaseService.dbName, latestVersion, {
      upgrade(db, oldVersion, newVersion, transaction) {
        console.log("ugrading. ", oldVersion, "->", newVersion)

        if (oldVersion < 1) {
          const notesStore = db.createObjectStore('notes', { keyPath: 'uuid' });
          notesStore.createIndex('by-updated', 'updated_at');
          notesStore.createIndex('by-created', 'created_at');
          db.createObjectStore('sync');
        }

        if (oldVersion < 2) {
          // 直接从 transaction 拿到已经存在的 store
          const notesStore = transaction.objectStore('notes');
          const indexNames = Array.from(notesStore.indexNames);

          if (indexNames.includes('by-mtime')) {
            notesStore.deleteIndex('by-mtime');
          }
          if (indexNames.includes('by-ctime')) {
            notesStore.deleteIndex('by-ctime');
          }

          // 这里再做索引创建
          if (!indexNames.includes('by-updated')) {
            notesStore.createIndex('by-updated', 'updated_at');
          }
          if (!indexNames.includes('by-created')) {
            notesStore.createIndex('by-created', 'created_at');
          }

          // 下面是关键：把旧的 ctime / mtime 改成新的 created_at / updated_at
          const allNotesPromise = notesStore.getAll();
          allNotesPromise.then((allNotes: NoteWithLegacyFields[]) => {
            allNotes.forEach(oldRecord => {
              const newRecord: Note = {
                ...oldRecord,
                created_at: oldRecord.ctime!,  // 使用类型断言，因为我们知道旧数据一定有这个字段
                updated_at: oldRecord.mtime!,
              };

              delete (newRecord as any).ctime;
              delete (newRecord as any).mtime;

              console.log("newRecord: ", newRecord)
              notesStore.put(newRecord);
            });
          });
        }
        if (oldVersion < 3) {
          // init TODO store
          const todoStore = db.createObjectStore('todos', { keyPath: 'uuid' });
          todoStore.createIndex('by-parent', 'parent_uuid');
          todoStore.createIndex('by-updated', 'updated_at');
        }

        if (oldVersion < 4) {
          // 创建status字段，默认为0，但如果deleted_at不是null，那么这里是1
          const notesStore = transaction.objectStore('notes');
          notesStore.createIndex('by-status', 'status', { unique: false });
          const allNotesPromise = notesStore.getAll();
          allNotesPromise.then((allNotes: NoteWithLegacyFields[]) => {
            allNotes.forEach(oldRecord => {
              const newRecord: Note = {
                ...oldRecord,
                status: oldRecord.deleted_at ? 1 : 0,
              };
              notesStore.put(newRecord);
            });
          });
        }

        console.log("upgrade done");
      }
    });
  }

  private static async ensureInitialized() {
    if (DatabaseService.db == undefined) {
      await DatabaseService.init();
    }
  }

  static async getNotes(since: Date | null) {
    await DatabaseService.ensureInitialized();
    const tx = DatabaseService.db!.transaction('notes', 'readonly');
    const store = tx.store;
    const index = store.index('by-updated');

    // 使用 IDBKeyRange.lowerBound 来获取所有在给定时间之后的记录
    const range = since ? IDBKeyRange.lowerBound(since.toISOString(), true) : undefined;
    return await index.getAll(range);
  }

  static async saveNote(note: Note, updateTimestamp: boolean = true) {
    this.updateNote(note, (draft) => {
      if (updateTimestamp) {
        draft.updated_at = new Date().toISOString();
      }
    })
  }

  static async getNotesPaginated(
    page: number,
    pageSize: number,
    sortOption: SortOption,
    dateRange?: DateRange
  ): Promise<{ notes: Note[], total: number }> {
    const sortBy = sortOption.field == 'updated_at' ? 'by-updated' : 'by-created'
    const order = sortOption.direction;

    await DatabaseService.ensureInitialized();
    const tx = DatabaseService.db!.transaction('notes', 'readonly');
    const store = tx.store;
    const index = store.index(sortBy);

    // 确定查询范围
    let range: IDBKeyRange | undefined = undefined;
    if (dateRange && dateRange.startDate && dateRange.endDate) {
      const startDateTime = `${dateRange.startDate}T00:00:00.000Z`;
      const endDateTime = `${dateRange.endDate}T23:59:59.999Z`;
      range = IDBKeyRange.bound(startDateTime, endDateTime);
    }


    console.log("getNotesPaginated: ", page, pageSize, sortOption, dateRange, range)

    // 单独拿总量
    const total = await index.count(range);
    console.log("total: ", total)

    // 使用游标遍历索引，同时应用过滤条件
    const notes: Note[] = [];
    const sortOrder = order === 'desc' ? 'prev' : 'next';

    const start = page * pageSize;
    let cursor = await index.openCursor(range, sortOrder); // 使用 'prev' 实现降序排序
    if(start > 0 && cursor) {
      cursor = await cursor.advance(start);
    }

    for(let i = 0; i < pageSize && cursor; i++) {
      const note = cursor.value;
      if (!note.deleted_at) {
        notes.push(note);
      } else {
        console.log("skipping deleted note: ", note)
      }
      if(cursor) {
        cursor = await cursor.continue();
      }
    }

    return { notes, total };
  }

  private static async updateNote(note: Note, updateFn: (draft: Note) => void) {
    const updatedNote = produce(note, updateFn);

    await DatabaseService.ensureInitialized();
    const tx = DatabaseService.db!.transaction('notes', 'readwrite');
    const store = tx.objectStore('notes');
    await store.put(updatedNote);
    await tx.done;
  }

  static async markNoteAsDeleted(note: Note) {
    const lastSyncOptional = await DatabaseService.getLastSync();
    if (lastSyncOptional != null && new Date(note.created_at) > new Date(lastSyncOptional.timestamp)) {
      // 如果笔记的创建时间在最后同步时间之后，则直接删除
      await DatabaseService.db!.delete('notes', note.uuid);
      return;
    }

    await DatabaseService.updateNote(note, (draft: Note) => {
      const now = new Date().toISOString();
      draft.updated_at = now;
      draft.deleted_at = now;
      draft.status = 1;
    });
  }

  static async getLastSync() {
    return await DatabaseService.db!.get('sync', 'lastSync');
  }

  static async setLastSync(timestamp: Date) {
    await DatabaseService.db!.put('sync', { timestamp: timestamp.toISOString() }, 'lastSync');
  }


  // Resolution/TODO related
  static async saveTodo(todo: Todo) {
    const updatedTodo = produce(todo, (draft: Todo) => {
      if (!draft.uuid) {
        draft.uuid = crypto.randomUUID();
      }

      const now = new Date().toISOString();
      draft.updated_at = now

    });
    await DatabaseService.ensureInitialized();
    await DatabaseService.db!.put('todos', updatedTodo);
  }

  static async getTodosByParentId(parentId: string): Promise<Todo[]> {
    await DatabaseService.ensureInitialized();
    const tx = DatabaseService.db!.transaction('todos', 'readonly');
    const index = tx.store.index('by-parent');
    return await index.getAll(parentId);
  }

  static async deleteTodo(id: string) {
    await DatabaseService.ensureInitialized();
    await DatabaseService.db!.delete('todos', id);
  }

  static async toggleTodoComplete(id: string) {
    await DatabaseService.ensureInitialized();
    const todo = await DatabaseService.db!.get('todos', id);
    if (todo) {
      todo.completed = !todo.completed;
      await DatabaseService.saveTodo(todo);
    }
  }

  // 删除所有在after时间点之后，状态为1的笔记
  // 如果传入了 after，则只删除在after时间点之后，状态为1的笔记
  static async deleteMarkedNotes(after: Date | null) {
    await DatabaseService.ensureInitialized();
    const tx = DatabaseService.db!.transaction('notes', 'readwrite');
    const store = tx.objectStore('notes');
    const index = store.index('by-status');

    // 获取所有标记为删除的笔记
    const deletedNotes = await index.getAll(IDBKeyRange.only(1)); // 假设 status 为 1 表示已删除

    for (const note of deletedNotes) {
      if(!after || new Date(note.created_at) > after) {
        await store.delete(note.uuid);
      }
    }

    await tx.done;
  }
}