import React, { useRef, useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { DatabaseService } from '../services/db';
import { generateUUID } from '../utils/uuid';
import { Note } from '../types';
import { useDispatch, useSelector } from 'react-redux';
import { Action, dispatchThenReload, State } from '../store';
import EditableNote from './EditableNote';
import { ThunkDispatch } from 'redux-thunk';
import { UnknownAction } from '@reduxjs/toolkit';

const AddNote: React.FC = () => {
    const {addingNote, pagination} = useSelector((state: State) => ({
        addingNote: state.addingNote,
        pagination: state.pagination
    }));

    const dispatch: ThunkDispatch<State, void, UnknownAction> = useDispatch();
    const { t } = useTranslation();
    const containerRef = useRef<HTMLDivElement>(null);

    const saveNote = async (content: string) => {
        if (content.trim()) {
            const newNote: Note = {
                id: Date.now(),
                uuid: generateUUID(),
                created_at: new Date().toISOString(),
                updated_at: new Date().toISOString(),
                content: content,
                status: 0,
            };
            await DatabaseService.saveNote(newNote);
            dispatch(dispatchThenReload((dispatch, getState) => {
                dispatch(Action.setAddingNote(false));
            }));
        }
    };

    const cancelAddNote = () => {
        dispatch(Action.setAddingNote(false));
    };

    useEffect(() => {
        if (addingNote && containerRef.current) {
            // 给一个小延迟确保编辑器已经完全渲染
            setTimeout(() => {
                const textarea = containerRef.current?.querySelector('textarea');
                if (textarea) {
                    textarea.focus();
                }
            }, 100);
        }
    }, [addingNote]);

    return addingNote ? (
        <EditableNote
            initialContent={""}
            onSave={saveNote}
            onCancel={cancelAddNote}
            ref={containerRef}
        />
    ) : null;
};

export default AddNote;