import { configureStore, createAction, createAsyncThunk, createReducer, Middleware, Reducer, ThunkDispatch, UnknownAction } from '@reduxjs/toolkit';
import { DateRange, Note, Pagination, SortOption } from '../types';
import { DatabaseService } from '../services/db';
import { ApiService } from '../services/api';

function getTimeStampString(date: Date | null): string | null {
  if(date == null) {
    return null
  }
  return date.toISOString();
}

export interface State {
  notes: Note[];

  // 状态相关
  username: string;
  isSyncing: boolean;
  editingNote: Note | null;
  addingNote: boolean;

  toasts: Toast[];

  pagination: Pagination;
}

export type Toast = { id: number; message: string ; color?: "default" | "green" | "yellow" | "red" }

export function dispatchThenReload(callback: (dispatch: ThunkDispatch<State, void, UnknownAction>, getState: () => State) => void) {
  return (dispatch: ThunkDispatch<State, void, UnknownAction>, getState: () => State) => {
    callback(dispatch, getState);
    dispatch(Action.loadLocalNotesThunk(getState().pagination));
  }
}

export const Action = {
  login: createAction<string>('LOGIN'),
  logout: createAction<void>('LOGOUT'),
  setNotes: createAction<{ notes: Note[], total: number }>('SET_NOTES'),
  setDateRange: createAction<DateRange>('SET_DATE_RANGE'),
  setSortOption: createAction<SortOption>('SET_SORT_OPTION'),
  setEditingNote: createAction<Note | null>('SET_EDITING_NOTE'),
  setAddingNote: createAction<boolean>('SET_ADDING_NOTE'),

  removeToast: createAction<number>('REMOVE_TOAST'),
  addToast: createAction<Toast>('ADD_TOAST'),

  // TODO: 异步action
  setPage: createAction<number>('SET_PAGE'),

  showToastThunk: createAsyncThunk("SHOW_TOAST", async ({ toast, duration = 10000 }: { toast: Toast, duration?: number }, thunkAPI) => {
    thunkAPI.dispatch(Action.addToast(toast))

    setTimeout(() => {
      thunkAPI.dispatch(Action.removeToast(toast.id));
    }, duration);
  }),

  // 这个thunk也会用来给其他的thunk提供支持
  loadLocalNotesThunk: createAsyncThunk("LOAD_LOCAL_NOTES",
    async ({ currentPage, pageSize, sortOption, dateRange }: Pagination) => {
      try {
        return await DatabaseService.getNotesPaginated(
          currentPage,
          pageSize,
          sortOption,
          dateRange
        );
      } catch (error) {
        console.error('加载本地笔记失败:', error);
        return { notes: [], total: 0 };
      }
    }),

  syncNotesThunk: createAsyncThunk<void, void, { state: State }>(
    'SYNC_NOTES',
    async (_, { dispatch, getState }) => {
      const now: Date = new Date();

      try {
        const lastSync = await DatabaseService.getLastSync();
        const since: Date | null = lastSync ? new Date(lastSync.timestamp) : null;

        // 在同步之前，清除掉之前所有标记删除的笔记
        await DatabaseService.deleteMarkedNotes(since);

        const notes = await DatabaseService.getNotes(since);

        const syncRequest = {
          updated_since: getTimeStampString(since),
          notes: notes
        };

        const response = await ApiService.syncNotes(syncRequest);
        if (response.error) {
          if (response.code === 401) {
            localStorage.removeItem('token');
            dispatch(Action.logout());
            return;
          }

          const toast: Toast = { id: Date.now(), message: response.error, color: "red" };
          dispatch(Action.showToastThunk({ toast }));
        } else {
          const server_newer = response.server_newer || [];
          const only_on_server = response.only_on_server || [];

          for (const note of [...server_newer, ...only_on_server]) {
            await DatabaseService.saveNote(note, false);
          }

          // 因为我们已经同步了，所以可以删除 *所有* 掉标记为删除的笔记
          await DatabaseService.deleteMarkedNotes(null);

          await DatabaseService.setLastSync(now);

          const state = getState();
          dispatch(Action.loadLocalNotesThunk(state.pagination));
          const toast: Toast = { id: Date.now(), message: '同步成功', color: "green" };
          dispatch(Action.showToastThunk({ toast }));
        }
      } catch (error) {
        const toast: Toast = { id: Date.now(), message: '同步失败', color: "yellow" };
        dispatch(Action.showToastThunk({ toast }));
        console.error('同步失败:', error);
      }
    }
  ),
};

// TODO: split into different reducers
export const initialState: State = {
  notes: [],
  username: '',
  isSyncing: false,
  pagination: { total: 1, currentPage: 0, pageSize: 10, sortOption: { field: 'created_at', direction: 'desc' }, dateRange: { startDate: '', endDate: '' } },
  editingNote: null,
  addingNote: false,
  toasts: [],
};

// TODO: split into different reducers
export const noteReducer = createReducer(initialState, (builder) => {
  builder
    .addCase(Action.login, (state, action) => { state.username = action.payload; })
    .addCase(Action.logout, (state) => {
      state.username = "";
      state.notes = [];
    })
    .addCase(Action.loadLocalNotesThunk.pending, (state, action) => {
      // do nothing, just to avoid warning on this action
    })
    .addCase(Action.loadLocalNotesThunk.fulfilled, (state, action) => {
      const { notes, total } = action.payload;
      state.notes = notes;
      state.pagination.total = total;
    })
    .addCase(Action.setDateRange, (state, action) => { state.pagination.dateRange = action.payload; })
    .addCase(Action.setSortOption, (state, action) => { state.pagination.sortOption = action.payload; })
    .addCase(Action.setPage, (state, action) => { state.pagination.currentPage = action.payload; })
    .addCase(Action.setEditingNote, (state, action) => { state.editingNote = action.payload; })
    .addCase(Action.setAddingNote, (state, action) => { state.addingNote = action.payload; })
    .addCase(Action.addToast, (state, action) => { state.toasts.push(action.payload); })
    .addCase(Action.removeToast, (state, action) => {
      state.toasts = state.toasts.filter(toast => toast.id !== action.payload);
    })
    .addCase(Action.syncNotesThunk.pending, (state) => { state.isSyncing = true; })
    .addMatcher(
      (action) => action.type == Action.syncNotesThunk.fulfilled.type || action.type == Action.syncNotesThunk.rejected.type,
      (state) => { state.isSyncing = false;}
    )
    .addDefaultCase((state, action) => {
      if (debugEnabled) {
        console.error("unknown action: ", action);
      }
    });
});

// only enable debug in development mode
const debugEnabled = process.env.NODE_ENV === 'development' ? true : false;

const loggerMiddleware: Middleware = store => next => action => {
  if (debugEnabled) {
    console.log('Dispatching:', action);
  }
  const result = next(action);
  if (debugEnabled) {
    console.log('Next State:', store.getState());
  }
  return result;
};

export const store = configureStore({
    reducer: noteReducer, 
    middleware: (getDefaultMiddleware) => getDefaultMiddleware().concat(loggerMiddleware)});

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
